-- Localized question wording preserves IDs, answer order, weights and scoring.
update public.school_marketing set questions=(select jsonb_agg(q.value||jsonb_build_object('category_en',en.value->0,'prompt_en',en.value->1,'options_en',en.value->2) order by q.n) from jsonb_array_elements(questions) with ordinality q(value,n) join jsonb_array_elements($en$[["Student data", "A transfer student registers today. How does your team find and update their records?", ["Find paper files and copy the forms", "Update each staff member's spreadsheet", "Update one record used across departments", "The system checks duplicates and alerts relevant teams", "Validated data helps plan the services the student needs"]], ["Academic planning", "How are classes and teaching assignments prepared for a new academic year?", ["Write lists on paper", "Combine files from each coordinator", "Set up classes, teachers, and semesters in a shared system", "The system checks scheduling conflicts and capacity", "Use projected needs to compare planning scenarios"]], ["Attendance", "A student is absent from the first lesson. What happens?", ["The teacher records it and contacts the family separately", "Records are entered in a spreadsheet after class", "Authorized people can view attendance immediately", "Notifications and follow-up follow agreed rules", "Absence patterns guide interventions whose results are evaluated"]], ["Learning materials", "A substitute teacher needs tomorrow's lesson materials. How do they get them?", ["Ask the previous teacher for books or notes", "Search chat messages or personal folders", "Open materials organized by course and lesson", "Materials, assignments, and class progress are connected", "Learning progress helps select suitable next materials"]], ["Assignments", "A parent asks which assignments their child has not submitted. How do you answer?", ["Ask each teacher individually", "Compare assignment files and grade lists", "Open that child's assignments and submissions", "The system shows deadlines and sends reminders", "Evaluate late-submission patterns and the effectiveness of support"]], ["Assessment", "Teachers want to reuse high-quality questions. How do they do it?", ["Search old printed exam papers", "Search question files on individual computers", "Select from a question bank organized by subject", "Questions undergo review and analysis of previous use", "Question-quality data supports regular assessment improvements"]], ["Exam delivery", "Many classes start exams at the same time. How does the school prepare?", ["Hand out printed papers and mark them manually", "Use online forms without load testing", "Schedule digital sessions with accounts and saved answers", "Test capacity and connection recovery before the exam", "Monitor service indicators and regularly evaluate resilience"]], ["Billing", "A parent wants details of unpaid bills. How do they get them?", ["Ask for records at the school counter", "Receive files or photos prepared by staff", "View connected bills and payment records", "Balances reconcile automatically with a history of changes", "Payment trends support planning and fair services"]], ["Financial reporting", "The principal needs the school's financial position this afternoon. How is it prepared?", ["Collect notebooks from several desks", "Combine spreadsheets and recalculate", "Generate a report from shared transaction records", "Review exceptions through connected reports and approvals", "Compare forecasts with actual results to decide next actions"]], ["Communication", "A teacher needs to contact a parent authorized to receive a student's information. What is the process?", ["Find a phone number in a printed list", "Search for contacts across chat groups", "Contact the parent account linked to the student", "Conversations connect to classes or tasks with clear access rules", "Evaluate communication reach and effectiveness"]], ["Calendar", "A school event changes date. How does everyone learn about it?", ["Print a new announcement", "Resend messages in several groups", "Update one shared school calendar", "The calendar sends notifications and requests responses", "Evaluate attendance and scheduling conflicts for future planning"]], ["School projects", "An event committee needs to identify overdue work. How is it tracked?", ["Ask during meetings", "Share a task list in spreadsheets or chat", "View a task board with owners and deadlines", "Dependencies, budgets, and approvals follow the project", "Delivery data improves future event templates"]], ["Facilities", "Two teachers want the laboratory at the same time. What happens?", ["Check the booking notebook and coordinate", "Check a timetable shared manually", "View availability in a shared booking system", "The system rejects conflicts and routes approvals", "Usage and capacity inform facility investment decisions"]], ["User access", "An employee leaves the school. How is access handled?", ["Rely on changing shared passwords", "Remove access from each application using a checklist", "Deactivate the account and its assigned roles", "Revocation procedures and cross-module audits are integrated", "Regular access reviews test and improve controls"]], ["Data security", "The school needs to recover important deleted information. What preparation exists?", ["There are no regular copies", "Occasional copies are made on another device", "Scheduled backups and responsibilities are established", "Recovery is tested against time targets with an audit trail", "Recovery exercises inform regular risk reduction"]], ["Parent services", "A parent has a question about their child's progress. What is the experience?", ["Visit the school and contact each department", "Exchange messages across separate channels", "One access point shows relevant child information", "Questions connect to records and staff follow-up", "Feedback and resolution times guide service improvements"]], ["Decision making", "The principal wants to identify classes needing extra support. What informs the decision?", ["Meeting impressions and informal stories", "Occasional summary reports", "Academic and attendance data are available in a dashboard", "Combined indicators lead to measurable follow-up", "Evaluate intervention outcomes and improve strategies"]], ["Teacher development", "A new digital feature launches. How are teachers supported?", ["Learn independently without guidance", "Attend one introductory session", "Receive guides, training, and a support channel", "Usage and difficulties are reviewed with ongoing assistance", "A teacher community shares practice and measures learning impact"]], ["Integration", "A student's name is corrected. Where must it be changed?", ["In every printed document", "Manually in several files and applications", "In one master record read by other modules", "Validation and synchronization prevent inconsistent data", "Data quality and integration processes are reviewed regularly"]], ["Transformation roadmap", "The school plans next year's digital investment. How are priorities chosen?", ["React to urgent needs", "Buy currently popular tools", "Use a map of school needs and goals", "Compare benefits, costs, and process readiness", "Measure investment results and update the roadmap based on evidence"]]]$en$::jsonb) with ordinality en(value,n) using(n)) where id;
update public.school_plans set features_en='["School administration foundations","Digital adoption support"]' where code='ESSENTIAL' and features='["Fondasi administrasi sekolah","Pendampingan digitalisasi"]';
update public.school_plans set features_en='["Connected school processes","Support for improving school services"]' where code='ELEVATE' and features='["Integrasi proses sekolah","Pendampingan peningkatan layanan"]';
update public.school_plans set features_en='["School transformation consulting","Advanced integration planning"]' where code='ENTERPRISE' and features='["Konsultasi transformasi sekolah","Perencanaan integrasi lanjutan"]';
